using System.Text.Json;
using Vebram.Revit;
var passed=new List<string>();
void Check(bool condition,string title){if(!condition)throw new Exception(title);passed.Add(title);}
bool Near(double a,double b)=>Math.Abs(a-b)<1e-7;
Check(RoomNameText.Display("SUÍTE 1")=="SUÍTE 1","Número legítimo no nome preservado");
Check(RoomNameText.Display("  SUÍTE 1 07 07  ")=="SUÍTE 1 07 07","Nome suspeito não é reescrito sem confirmação");
Check(RoomNameText.NeedsReview("SUÍTE 1 07","07"),"Possível sufixo de transferência sinalizado");
Check(RoomNameText.NeedsReview("SUÍTE 1","1"),"Caso ambíguo exige revisão, sem apagar número");
Check(!RoomNameText.NeedsReview("SUÍTE 1","07"),"Nome normal não é marcado pelo número de outro ambiente");
Check(!RoomNameText.NeedsReview("SUÍTE 107","07"),"Número parcial não é tratado como sufixo");
Check(RoomNameText.RestoreFromReference("SUÍTE 1 07 07","07","SUÍTE 1")=="SUÍTE 1","Nome restaurado pela referência original");
Check(RoomNameText.RestoreFromReference("SUÍTE 1 1 1","1","SUÍTE 1")=="SUÍTE 1","Número legítimo da referência mantido na restauração");
Check(RoomNameText.RestoreFromReference("SUÍTE RENOMEADA 07","07","SUÍTE 1")=="SUÍTE RENOMEADA 07","Nome manual diferente da referência preservado");
Check(Near(LegalMetrics.PolygonArea(new[]{(0d,0d),(20d,0d),(20d,30d),(0d,30d)}),600),"Lote 20 × 30 m = 600 m²");
Check(Near(LegalMetrics.PolygonArea(new[]{(0d,30d),(20d,30d),(20d,0d),(0d,0d)}),600),"Orientação invertida conserva área");
Check(Near(LegalMetrics.PolygonArea(new[]{(0d,0d),(10d,0d),(10d,5d),(5d,5d),(5d,10d),(0d,10d)}),75),"Contorno ortogonal côncavo = 75 m²");
Check(Near(LegalMetrics.PolygonArea(new[]{(1e9,1e9),(1e9+20,1e9),(1e9+20,1e9+30),(1e9,1e9+30)}),600),"Coordenadas distantes sem perda por cancelamento");
Check(Near(LegalMetrics.PolygonArea(new[]{(0d,0d),(12d,0d),(14.5,2.5),(15.2,26d),(-1d,24.5)}),383.7),"CT04: área do polígono real com chanfro = 383,70 m²");
Check(!Near(LegalMetrics.PolygonArea(new[]{(0d,0d),(12d,0d),(14.5,2.5),(15.2,26d),(-1d,24.5)}),16.2*26),"Retângulo envolvente não substitui área do lote irregular");
Check(Near(LegalMetrics.Ratio(150,600,true),25),"TO 150 / 600 = 25%");
Check(Near(LegalMetrics.Ratio(900,600,false),1.5),"CA 900 / 600 = 1,5");
Check(Near(LegalMetrics.Ratio(120,600,true),20),"TP 120 / 600 = 20%");
Check(LegalMetrics.Compare(20,null,true)=="limite não informado","Limite ausente não gera aprovação");
Check(LegalMetrics.Compare(70,70,true)=="dentro do limite informado","Máximo inclusivo");
Check(LegalMetrics.Compare(71,70,true)=="fora do limite informado","Máximo excedido");
Check(LegalMetrics.Compare(19,20,false)=="fora do limite informado","Mínimo não atingido");
bool invalid=false;try{LegalMetrics.Ratio(10,0,true);}catch(ArgumentOutOfRangeException){invalid=true;}Check(invalid,"Área nula recusada");
var usable=new LegalPaperRect(0,0,10,8);var item=new LegalPaperRect(-2,-1,2,1);
var first=usable.FindFree(Array.Empty<LegalPaperRect>(),item,.1,.2);Check(first.HasValue&&usable.Contains(first.Value),"Primeira vista cabe dentro da folha");
var second=usable.FindFree(new[]{first!.Value},item,.1,.2);Check(second.HasValue&&!first.Value.Intersects(second.Value,.2),"Segunda vista mantém espaço sem colisão");
Check(usable.FindFree(Array.Empty<LegalPaperRect>(),new(0,0,11,2),.1,.2)==null,"Vista maior que folha recusada");
Check(usable.FindFree(new[]{usable},item,.1,.2)==null,"Folha cheia recusada");
Check(new LegalPaperRect(0,0,1,1).Move(2,3)==new LegalPaperRect(2,3,3,4),"Deslocamento conserva dimensões");
Check(!new LegalPaperRect(0,0,1,1).Intersects(new(1,0,2,1),0),"Arestas apenas adjacentes não se sobrepõem");
Check(new LegalPaperRect(0,0,1,1).Intersects(new(1,0,2,1),.01),"Folga mínima detecta arestas adjacentes");
Check(RoofDrainageRules.Resolve(0,"Modelo",null).Slope==null,"Água plana sem proposta fica pendente");
Check(RoofDrainageRules.Resolve(12,"Modelo",new("a",5,"Direita")).Slope==12,"Inclinação modelada prevalece sobre proposta");
Check(RoofDrainageRules.Resolve(0,"Modelo",new("a",5,"Esquerda")).Flow=="Esquerda","Proposta por água preserva direção");
Check(RoofDrainageRules.Resolve(.049,"Modelo",null).Slope==null,"Tolerância de plano evita 0,0%");
foreach(var bad in new[]{new RoofDrainageChoice("a",0,"Direita"),new RoofDrainageChoice("a",-2,"Direita"),new RoofDrainageChoice("a",double.NaN,"Direita"),new RoofDrainageChoice("a",101,"Direita"),new RoofDrainageChoice("a",5,"Modelo")}){bool rejected=false;try{RoofDrainageRules.Resolve(0,"Modelo",bad);}catch(ArgumentException){rejected=true;}Check(rejected,"Proposta inválida recusada: "+bad);}
var house=new List<BuildingBounds>{new(1.5,4,0,10.5,12.5,.15),new(1.5,12.5,0,10.5,16,.15),new(1.5,9.5,-2.85,10.5,16,-.15),new(1.5,9.5,-3,10.5,16,-2.85),new(1.5,15.9,.15,10.5,16.1,1.25),new(30,30,0,40,40,3)};
var connected=BuildingEnvelope.Connected(house,0,.35);
Check(connected.SetEquals(new[]{0,1,2,3,4}),"CT03 inclui terraço, inferior abaixo da rua e guarda-corpos; exclui edificação remota");
Check(BuildingEnvelope.Connected(house,3,.35).SetEquals(connected),"Fonte no inferior encontra a mesma casa completa");
Check(!new BuildingBounds(0,0,0,1,1,1).Touches(new(0,0,5,1,1,6),.35),"Proximidade em planta não conecta volumes separados em altura");
var triangle=new[]{new TerrainPoint(0,0,0),new TerrainPoint(10,0,-1),new TerrainPoint(0,20,-4)};
var slice=TerrainSlice.Triangle(triangle,new(0,5,0),new(0,1,0));
Check(slice!=null&&Near(slice.Value.A.Y,5)&&Near(slice.Value.B.Y,5),"Perfil pertence ao plano exato da vista");
Check(slice!=null&&Near(slice.Value.A.Z+slice.Value.A.X*.1,-1)&&Near(slice.Value.B.Z+slice.Value.B.X*.1,-1),"Perfil conserva declive e cotas negativas reais");
Check(TerrainSlice.Triangle(triangle,new(0,30,0),new(0,1,0))==null,"Plano fora do terreno não inventa linha plana");
Check(TerrainSlice.Triangle(triangle,new(10,0,0),new(1,0,0))==null,"Toque em um vértice não produz segmento de comprimento zero");
Check(TerrainSlice.Triangle(triangle,new(0,0,0),new(0,1,0))!=null,"Plano sobre uma aresta mantém o trecho real");
Check(TerrainSlice.Triangle(triangle,new(0,0,0),new(.1,.2,1))==null,"Triângulo coplanar não produz aresta arbitrária");
var report=new{Scope="Aritmética, envelopes, perfis de terreno e retângulos do código de produção; não testa Revit, geometria nativa, marcadores ou viewport real.",Passed=passed.Count,Checks=passed};
var json=JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true});Console.WriteLine(json);if(args.Length>0)File.WriteAllText(args[0],json);
